def lexicographicallySmallest(S, k):
    n = len(S)
    if n & (n - 1) == 0:  # Check if n is a power of 2
        k //= 2
    else:
        k *= 2

    if k > n:
        return -1

    stack = []
    for char in S:
        while k > 0 and stack and stack[-1] > char:
            stack.pop()
            k -= 1
        stack.append(char)

    while k > 0:
        stack.pop()
        k -= 1

    result = ''.join(stack)
    return result
